rules:
start
capture "year" {
4 digits
}
"-"
capture "month" {
2 digits
}
"-"
capture "day" {
2 digits
}
end

"."
capture "extension" {
  either {
    "txt"
    "md"
    "json"
  }
}
end

start
"https://"
one or more character class: range "A" to "Z", range "a" to "z", digit
zero or more group {
  one of: "-", "."
  one or more character class: range "A" to "Z", range "a" to "z", digit
}
optional group {
  "/"
  zero or more not space
}
end

start
capture "field" {
  one or more character class: range "A" to "Z", range "a" to "z", "-"
}
": "
capture "value" {
  one or more none of: "\r", "\n", "\u0000", "\u2028", "\u2029"
}
end

start
capture "major" {
  either {
    "0"
    group {
      range "1" to "9"
      zero or more digit
    }
  }
}
"."
capture "minor" {
  either {
    "0"
    group {
      range "1" to "9"
      zero or more digit
    }
  }
}
"."
capture "patch" {
  either {
    "0"
    group {
      range "1" to "9"
      zero or more digit
    }
  }
}
optional group {
  "-"
  capture "prerelease" {
    either {
      "0"
      group {
        range "1" to "9"
        zero or more digit
      }
      group {
        zero or more digit
        character class: range "A" to "Z", range "a" to "z", "-"
        zero or more character class: range "A" to "Z", range "a" to "z", digit, "-"
      }
    }
    zero or more group {
      "."
      either {
        "0"
        group {
          range "1" to "9"
          zero or more digit
        }
        group {
          zero or more digit
          character class: range "A" to "Z", range "a" to "z", "-"
          zero or more character class: range "A" to "Z", range "a" to "z", digit, "-"
        }
      }
    }
  }
}
optional group {
  "+"
  capture "build" {
    one or more character class: range "A" to "Z", range "a" to "z", digit, "-"
    zero or more group {
      "."
      one or more character class: range "A" to "Z", range "a" to "z", digit, "-"
    }
  }
}
end

start
either {
  40 hex digits
  64 hex digits
}
end

capture "level" {
  either {
    "INFO"
    "WARN"
    "ERROR"
  }
}
" code="
capture "code" {
  3 digits
}

word boundary
capture "word" {
  "teh"
}
word boundary
